static uint32_t le24(const uint8_t*p){return p[0]|(uint32_t(p[1])<<8)|(uint32_t(p[2])<<16);}
static Astc readAstc(const std::string&path){std::vector<uint8_t>b; if(!load(path,b)||b.size()<16)throw std::runtime_error("cannot read ASTC header/payload: "+path);
    if(b[0]!=0x13||b[1]!=0xAB||b[2]!=0xA1||b[3]!=0x5C)throw std::runtime_error("invalid ASTC magic");
    Astc a; a.bx=b[4];a.by=b[5]; if(b[6]!=1||(a.bx!=8&&a.bx!=12)||a.by!=a.bx)throw std::runtime_error("only 2D 8x8 or 12x12 ASTC supported");
    a.w=le24(&b[7]);a.h=le24(&b[10]); if(!a.w||!a.h||le24(&b[13])!=1)throw std::runtime_error("invalid ASTC dimensions; require 2D depth 1");
    const size_t expected=size_t((a.w+a.bx-1)/a.bx)*((a.h+a.by-1)/a.by)*16;
    if(b.size()!=16+expected)throw std::runtime_error("ASTC block payload size mismatch"); a.data.assign(b.begin()+16,b.end());return a;
}
