static void csv(std::ostream&o,const char*name,const Stats&s){for(size_t i=0;i<s.total.size();++i)o<<name<<','<<i<<','<<s.up[i]<<','<<s.sample[i]<<','<<s.total[i]<<','<<s.cpu[i]<<'\n';}
